-- ElectroShop: isolated schema. Existing public tables are not altered.
create schema if not exists electroshop;
revoke all on schema electroshop from public;
grant usage on schema electroshop to anon, authenticated;
alter default privileges in schema electroshop revoke execute on functions from public;
create table electroshop.roles(email text primary key, role text not null check(role in ('admin','delivery')));
create table electroshop.products(id bigint generated by default as identity primary key, data jsonb not null, active boolean not null default true,
 check(length(data->>'name') between 1 and 150), check((data->>'price_paise')::bigint>0), check((data->>'stock')::integer>=0));
create table electroshop.customers(user_id uuid primary key references auth.users(id) on delete cascade, data jsonb not null default '{}');
create table electroshop.orders(id text primary key, user_id uuid not null references auth.users(id), data jsonb not null, created_at timestamptz not null default now());
create index shop_orders_user_idx on electroshop.orders(user_id,created_at desc);
create index shop_orders_assignee_idx on electroshop.orders((data->>'assigned_to'));
create table electroshop.reviews(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), product_id bigint not null references electroshop.products(id), data jsonb not null, unique(user_id,product_id));
create index shop_reviews_product_idx on electroshop.reviews(product_id);
create table electroshop.returns(id text primary key, user_id uuid not null references auth.users(id), order_id text not null references electroshop.orders(id), product_id bigint not null references electroshop.products(id), data jsonb not null, unique(order_id,product_id));
create index shop_returns_user_idx on electroshop.returns(user_id);
alter table electroshop.roles enable row level security;
alter table electroshop.products enable row level security;
alter table electroshop.customers enable row level security;
alter table electroshop.orders enable row level security;
alter table electroshop.reviews enable row level security;
alter table electroshop.returns enable row level security;
revoke all on all tables in schema electroshop from anon,authenticated;
revoke all on all sequences in schema electroshop from anon,authenticated;
-- The signed-in, verified account email is read from Auth, never user_metadata.
insert into electroshop.roles values ('adityaraj3532@gmail.com','admin');
create function electroshop.current_role() returns text language sql stable security definer set search_path='' as $$
 select case when auth.uid() is null then 'customer' else coalesce((select r.role from electroshop.roles r join auth.users u on lower(u.email)=r.email where u.id=auth.uid() and u.email_confirmed_at is not null),'customer') end;
$$;
create function electroshop.review_eligible(pid bigint) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from electroshop.orders o where o.user_id=auth.uid() and o.data->>'status'='Delivered' and (o.data->'items') @> jsonb_build_array(jsonb_build_object('product_id',pid)));
$$;
create function electroshop.api(p_path text,p_method text default 'GET',p_body jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare
 uid uuid:=auth.uid(); em text; role_name text:=electroshop.current_role(); result jsonb:='{}'; v jsonb; prod jsonb; item jsonb; items jsonb:='[]'; ord jsonb; rec jsonb; pid bigint; qty integer; subtotal bigint:=0; total bigint; stock integer; oid text; rid text; oldstatus text; newstatus text; nowepoch bigint:=extract(epoch from now())::bigint; allowed text[]; assignee text; iid record; day_count integer;
begin
 if octet_length(p_body::text)>100000 then raise exception 'Request too large'; end if;
 if uid is not null then select lower(email) into em from auth.users where id=uid and email_confirmed_at is not null; if em is null then raise exception 'A verified sign-in is required'; end if; end if;
 if p_path='/snapshot' and p_method='GET' then
  return jsonb_build_object('user',case when uid is null then null else jsonb_build_object('id',uid,'email',em,'role',role_name) end,
   'products',coalesce((select jsonb_agg(p.data||jsonb_build_object('id',p.id,'active',case when p.active then 1 else 0 end) order by p.id desc) from electroshop.products p where p.active or role_name='admin'),'[]'::jsonb),
   'orders',coalesce((select jsonb_agg(o.data order by o.created_at desc) from electroshop.orders o where uid is not null and (o.user_id=uid or role_name='admin' or (role_name='delivery' and o.data->>'assigned_to'=em and o.data->>'status' not in ('Placed','Cancelled')))),'[]'::jsonb),
   'reviews',coalesce((select jsonb_agg((r.data-'order_id')||jsonb_build_object('id',r.id,'product_id',r.product_id)||case when r.user_id=uid then jsonb_build_object('email',em,'order_id',r.data->>'order_id') else '{}'::jsonb end) from electroshop.reviews r),'[]'::jsonb),
   'returns',coalesce((select jsonb_agg(r.data) from electroshop.returns r where uid is not null and (r.user_id=uid or role_name='admin')),'[]'::jsonb),
   'customer',coalesce((select c.data from electroshop.customers c where c.user_id=uid),'{}'::jsonb));
 end if;
 if uid is null then raise exception 'Please sign in first'; end if;
 if p_path='/customer' and p_method='PUT' then
  if octet_length(p_body::text)>60000 or jsonb_typeof(p_body)<>'object' then raise exception 'Invalid profile data'; end if;
  v=jsonb_build_object('profile',coalesce(p_body->'profile','{}'),'addresses',coalesce(p_body->'addresses','[]'),'defaultAddress',coalesce(p_body->'defaultAddress','""'),'wishlist',coalesce(p_body->'wishlist','[]'),'later',coalesce(p_body->'later','[]'),'cart',coalesce(p_body->'cart','{}'));
  if jsonb_typeof(v->'addresses')<>'array' or jsonb_array_length(v->'addresses')>20 or jsonb_typeof(v->'profile')<>'object' then raise exception 'Invalid profile or addresses'; end if;
  insert into electroshop.customers values(uid,v) on conflict(user_id) do update set data=excluded.data; return jsonb_build_object('message','Saved');
 end if;
 if p_path like '/admin/%' and role_name<>'admin' then raise exception 'Owner access required'; end if;
 if p_path like '/admin/products%' then
  if p_method='DELETE' then update electroshop.products set active=false where id=split_part(p_path,'/',4)::bigint; return '{"message":"Product removed"}'; end if;
  if p_method not in ('POST','PUT') then raise exception 'Method not allowed'; end if;
  if length(trim(coalesce(p_body->>'name','')))<1 or length(p_body->>'name')>150 or length(trim(coalesce(p_body->>'brand','')))<1 then raise exception 'Enter a product name and brand'; end if;
  if coalesce(p_body->>'category','') not in ('Laptop','Charger','Camera','Headphone','Speaker','Microphone','Other') then raise exception 'Invalid category'; end if;
  if coalesce(p_body->>'price_paise','') !~ '^[0-9]+$' or (p_body->>'price_paise')::bigint not between 1 and 100000000 or coalesce(p_body->>'stock','') !~ '^[0-9]+$' or (p_body->>'stock')::integer>100000 then raise exception 'Invalid price or stock'; end if;
  day_count=case when coalesce((p_body->>'returnable')::boolean,false) then (p_body->>'return_days')::integer else 0 end;
  if coalesce((p_body->>'returnable')::boolean,false) and (day_count is null or day_count not between 1 and 30) then raise exception 'Return window must be 1–30 days'; end if;
  if coalesce(p_body->>'image_url','')<>'' and p_body->>'image_url' !~ '^https://' then raise exception 'Invalid photo URL'; end if;
  v=jsonb_build_object('name',trim(p_body->>'name'),'brand',left(trim(p_body->>'brand'),80),'category',p_body->>'category','description',left(coalesce(p_body->>'description',''),4000),'price_paise',(p_body->>'price_paise')::bigint,'stock',(p_body->>'stock')::integer,'returnable',coalesce((p_body->>'returnable')::boolean,false),'return_days',day_count,'image_url',left(coalesce(p_body->>'image_url',''),2000));
  if p_method='POST' then insert into electroshop.products(data) values(v) returning id into pid; else pid=split_part(p_path,'/',4)::bigint; update electroshop.products set data=v where id=pid and active; if not found then raise exception 'Product not found'; end if; end if;
  return v||jsonb_build_object('id',pid,'active',1);
 end if;
 if p_path='/orders' and p_method='POST' then
  if jsonb_typeof(p_body->'items') is distinct from 'array' or jsonb_array_length(p_body->'items') not between 1 and 100 then raise exception 'Your cart is empty or too large'; end if;
  if length(trim(coalesce(p_body->>'name','')))<2 or length(coalesce(p_body->>'name',''))>120 or coalesce(p_body->>'phone','') !~ '^[6-9][0-9]{9}$' or length(trim(coalesce(p_body->>'address','')))<10 or length(p_body->>'address')>1000 then raise exception 'Enter valid delivery details'; end if;
  if coalesce(p_body->>'payment_method','COD')<>'COD' then raise exception 'Online payments are not connected. Choose cash on delivery.'; end if;
  for item in select value from jsonb_array_elements(p_body->'items') loop
   if coalesce(item->>'quantity','') !~ '^[0-9]+$' or (item->>'quantity')::integer not between 1 and 100 or coalesce(item->>'product_id','') !~ '^[0-9]+$' then raise exception 'Invalid cart item'; end if;
  end loop;
  -- Sort row locks to avoid deadlocks; group duplicate product IDs before stock checks.
  for iid in select (value->>'product_id')::bigint as product_id,sum((value->>'quantity')::integer)::integer as quantity from jsonb_array_elements(p_body->'items') group by 1 order by 1 loop
   pid=iid.product_id;qty=iid.quantity;select data into prod from electroshop.products where id=pid and active for update;
   if prod is null or qty>100 or (prod->>'stock')::integer<qty then raise exception 'A product is unavailable or has insufficient stock. Refresh your cart.'; end if;
   subtotal=subtotal+(prod->>'price_paise')::bigint*qty;
   items=items||jsonb_build_array(jsonb_build_object('product_id',pid,'name',prod->>'name','quantity',qty,'price_paise',(prod->>'price_paise')::bigint,'returnable',coalesce((prod->>'returnable')::boolean,false),'return_days',coalesce((prod->>'return_days')::integer,0)));
   update electroshop.products set data=jsonb_set(data,'{stock}',to_jsonb((data->>'stock')::integer-qty)) where id=pid;
  end loop;
  total=subtotal+case when subtotal<100000 then 4900 else 0 end;oid='ES-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16));
  ord=jsonb_build_object('id',oid,'email',em,'name',trim(p_body->>'name'),'phone',p_body->>'phone','address',trim(p_body->>'address'),'items',items,'total_paise',total,'status','Placed','payment_method','COD','payment_status','Pay on delivery','created',nowepoch,'history',jsonb_build_array(jsonb_build_object('status','Placed','note','Waiting for owner confirmation','at',nowepoch,'actor','Customer')));
  insert into electroshop.orders(id,user_id,data) values(oid,uid,ord);return ord;
 end if;
 if p_path like '/admin/orders/%' or p_path like '/delivery/orders/%' then
  oid=split_part(p_path,'/',4);select data into ord from electroshop.orders where id=oid for update;if ord is null then raise exception 'Order not found'; end if;
  if role_name<>'admin' and (role_name<>'delivery' or ord->>'assigned_to' is distinct from em) then raise exception 'This delivery is not assigned to you'; end if;
  oldstatus=ord->>'status';newstatus=coalesce(p_body->>'status',oldstatus);
  if oldstatus='Placed' and (role_name<>'admin' or p_body ?| array['assigned_to','courier','tracking','eta']) then raise exception 'Owner confirmation is required before delivery'; end if;
  allowed=case oldstatus when 'Placed' then array['Confirmed','Cancelled'] when 'Confirmed' then array['Shipped','Cancelled'] when 'Shipped' then array['Out for delivery','Delivered','Delivery failed'] when 'Out for delivery' then array['Delivered','Delivery failed'] when 'Delivery failed' then array['Out for delivery'] else array[]::text[] end;
  if newstatus<>oldstatus and (not newstatus=any(allowed) or (role_name<>'admin' and newstatus not in ('Shipped','Out for delivery','Delivered','Delivery failed'))) then raise exception 'Invalid status transition'; end if;
  if length(trim(coalesce(p_body->>'note','')))<3 then raise exception 'Add a delivery note'; end if;
  if newstatus='Cancelled' and oldstatus<>newstatus then for item in select value from jsonb_array_elements(ord->'items') loop update electroshop.products set data=jsonb_set(data,'{stock}',to_jsonb((data->>'stock')::integer+(item->>'quantity')::integer)) where id=(item->>'product_id')::bigint; end loop;end if;
  if p_body ? 'assigned_to' then
   if role_name<>'admin' then raise exception 'Only the owner can assign deliveries'; end if;
   assignee=lower(trim(p_body->>'assigned_to'));
   if assignee<>'' then
    if not exists(select 1 from auth.users where lower(email)=assignee and email_confirmed_at is not null) then raise exception 'Delivery partner must sign in with this email before assignment'; end if;
    insert into electroshop.roles values(assignee,'delivery') on conflict(email) do update set role=case when electroshop.roles.role='admin' then 'admin' else 'delivery' end;
   end if;
   ord=ord||jsonb_build_object('assigned_to',assignee);
  end if;
  if p_body ? 'courier' then ord=ord||jsonb_build_object('courier',left(p_body->>'courier',100));end if;
  if p_body ? 'tracking' then ord=ord||jsonb_build_object('tracking',left(p_body->>'tracking',100));end if;
  if p_body ? 'eta' then ord=ord||jsonb_build_object('eta',left(p_body->>'eta',10));end if;
  if newstatus='Delivered' and oldstatus<>newstatus then ord=ord||jsonb_build_object('delivered_at',nowepoch);end if;
  ord=ord||jsonb_build_object('status',newstatus,'history',coalesce(ord->'history','[]')||jsonb_build_array(jsonb_build_object('status',newstatus,'note',left(p_body->>'note',500),'at',nowepoch,'actor',case when role_name='admin' then 'Shop owner' else 'Delivery partner' end)));
  update electroshop.orders set data=ord where id=oid;return ord;
 end if;
 if p_path='/returns' and p_method='POST' then
  select data into ord from electroshop.orders where id=p_body->>'order_id' and user_id=uid for update;
  select value into item from jsonb_array_elements(coalesce(ord->'items','[]')) where (value->>'product_id')::bigint=(p_body->>'product_id')::bigint;
  if ord is null or item is null then raise exception 'You can only return your own purchases';end if;
  if ord->>'status'<>'Delivered' or not coalesce((item->>'returnable')::boolean,false) or (ord->>'delivered_at') is null or nowepoch>(ord->>'delivered_at')::bigint+(item->>'return_days')::integer*86400 then raise exception 'This item is not returnable or its return window has closed';end if;
  if length(trim(coalesce(p_body->>'reason',''))) not between 5 and 1000 then raise exception 'Describe the return reason in 5–1000 characters';end if;
  if exists(select 1 from electroshop.returns where order_id=ord->>'id' and product_id=(item->>'product_id')::bigint) then raise exception 'A return request already exists';end if;
  rid='RETURN-'||gen_random_uuid()::text;rec=jsonb_build_object('id',rid,'order_id',ord->>'id','product_id',(item->>'product_id')::bigint,'name',item->>'name','quantity',(item->>'quantity')::integer,'status','Requested','reason',trim(p_body->>'reason'),'created',nowepoch,'notes','');
  insert into electroshop.returns values(rid,uid,ord->>'id',(item->>'product_id')::bigint,rec);return rec;
 end if;
 if p_path like '/admin/returns/%' and p_method='PUT' then
  rid=split_part(p_path,'/',4);select data into rec from electroshop.returns where id=rid for update;if rec is null then raise exception 'Return not found';end if;
  allowed=case rec->>'status' when 'Requested' then array['Approved','Rejected'] when 'Approved' then array['Received'] else array[]::text[] end;
  if not coalesce(p_body->>'status','')=any(allowed) then raise exception 'Invalid return transition';end if;
  if length(trim(coalesce(p_body->>'notes',''))) not between 3 and 1000 then raise exception 'Add a note for the customer';end if;
  if p_body->>'status'='Received' then update electroshop.products set data=jsonb_set(data,'{stock}',to_jsonb((data->>'stock')::integer+(rec->>'quantity')::integer)) where id=(rec->>'product_id')::bigint;end if;
  rec=rec||jsonb_build_object('status',p_body->>'status','notes',trim(p_body->>'notes'),'updated',nowepoch);update electroshop.returns set data=rec where id=rid;return rec;
 end if;
 if p_path='/reviews' and p_method='POST' then
  pid=(p_body->>'product_id')::bigint;
  if not exists(select 1 from electroshop.orders where id=p_body->>'order_id' and user_id=uid and data->>'status'='Delivered' and data->'items' @> jsonb_build_array(jsonb_build_object('product_id',pid))) then raise exception 'Only customers with a delivered purchase can review this item';end if;
  if coalesce(p_body->>'rating','') !~ '^[1-5]$' or length(trim(coalesce(p_body->>'text',''))) not between 3 and 2000 then raise exception 'Enter a rating from 1 to 5 and a review in 3–2000 characters';end if;
  if coalesce(p_body->>'photo','')<>'' and p_body->>'photo' not like 'https://fdtbmtfcueyfdlwvtrkb.supabase.co/storage/v1/object/public/electroshop-media/'||uid::text||'/reviews/'||pid::text||'/%' then raise exception 'Upload your own review photo first';end if;
  rec=jsonb_build_object('order_id',p_body->>'order_id','rating',(p_body->>'rating')::integer,'text',trim(p_body->>'text'),'display_name',left(coalesce(nullif(trim(p_body->>'display_name'),''),'Customer'),60),'photo',coalesce(p_body->>'photo',''),'updated',nowepoch);
  insert into electroshop.reviews(user_id,product_id,data) values(uid,pid,rec) on conflict(user_id,product_id) do update set data=excluded.data;return '{"message":"Review published"}';
 end if;
 raise exception 'Unknown operation';
end;
$$;
revoke execute on all functions in schema electroshop from public;
grant execute on function electroshop.api(text,text,jsonb),electroshop.current_role(),electroshop.review_eligible(bigint) to anon,authenticated;
-- Only the invoker wrapper is in an API-exposed schema.
create function public.electroshop_api(p_path text,p_method text default 'GET',p_body jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$ select electroshop.api(p_path,p_method,p_body); $$;
revoke all on function public.electroshop_api(text,text,jsonb) from public;
grant execute on function public.electroshop_api(text,text,jsonb) to anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('electroshop-media','electroshop-media',true,1048576,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy electroshop_media_insert on storage.objects for insert to authenticated with check(bucket_id='electroshop-media' and (storage.foldername(name))[1]=(select auth.uid())::text and (((storage.foldername(name))[2]='products' and electroshop.current_role()='admin') or ((storage.foldername(name))[2]='reviews' and electroshop.review_eligible(case when (storage.foldername(name))[3] ~ '^[0-9]+$' then (storage.foldername(name))[3]::bigint else -1 end))));
-- No storage overwrite/update/delete grant: every upload has a unique filename.
notify pgrst,'reload schema';
